  Lemma keptI_no0 : ~ In (0%bv : reg) keptI.
  Proof. unfold keptI. cbn [In]. intros Hin. repeat (destruct Hin as [E|Hin]; [apply (f_equal bv_unsigned) in E; discriminate E|]). exact Hin. Qed.

